'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const contract=require('../architecture/strategy-comparison-contract.cjs');
const base={schemaVersion:1,mode:'classic-demo',profile:'balanced',referencePriceUSD:'80000',firstEntryPriceUSD:'80000',riskFloorUSD:'60000',buyLadderLowerBoundUSD:'60000',cycleFirstEntryGapUSD:'1000',withinCycleReinforcementGapUSD:'8000',maxCycles:5,nominalCycleBudgetUSD:'1000',walletCashUSD:'2000',reportedIsolatedMarginUSD:'200',plannedMarginAddsUSD:'500',protectedCashUSD:'400'};
const run=(o={})=>contract.generate({...base,...o});
const fail=(obj,code)=>assert.throws(()=>run(obj),e=>e.code===code);
test('historical five cycles and 15 prices',()=>{const x=run();assert.equal(x.levels.length,15);assert.deepEqual(x.levels.slice(0,3).map(a=>a.entryPriceUSD),['80000','72000','64000']);assert.deepEqual(x.levels.slice(-3).map(a=>a.entryPriceUSD),['76000','68000','60000']);});
test('twenty thirty fifty nominal allocations',()=>{const r=run().levels.slice(0,3);assert.deepEqual(r.map(x=>x.nominalAllocationUSD),['200','300','500']);assert.deepEqual(r.map(x=>x.weightPercent),[20,30,50]);});
test('floor at 60k explicitly blocks last classical buy',()=>assert.deepEqual(run().blockers.filter(b=>b.code==='ENTRY_AT_OR_BELOW_RISK_FLOOR').map(b=>[b.cycle,b.stage]),[[5,3]]));
test('buy bound is distinct from risk floor',()=>{const x=run({buyLadderLowerBoundUSD:'62000'});assert.equal(x.riskFloorUSD,'60000');assert.ok(x.blockers.some(b=>b.code==='ENTRY_BELOW_LADDER_BOUND'));});
test('V20 base 240 1200 but clearly not full adaptive volatility',()=>{const x=run({mode:'v20-base-illustrative',cycleFirstEntryGapUSD:'240',withinCycleReinforcementGapUSD:'1200'});assert.equal(x.levels.at(-1).entryPriceUSD,'76640');assert.ok(x.warnings.some(w=>w.includes('omit the higher volatility')));});
test('immutable historical and baseline modes cannot be overwritten',()=>{fail({cycleFirstEntryGapUSD:'1100'},'CLASSIC_PRESET_IS_IMMUTABLE');fail({mode:'v20-base-illustrative',cycleFirstEntryGapUSD:'241',withinCycleReinforcementGapUSD:'1200'},'V20_BASE_PRESET_IS_IMMUTABLE');});
test('adjustable preview allows independent buy spacing, but never authorizes orders',()=>{const r=run({mode:'adjustable-preview',cycleFirstEntryGapUSD:'1500',withinCycleReinforcementGapUSD:'7000'});assert.equal(r.levels.at(-1).entryPriceUSD,'60000');assert.equal(r.canApply,false);assert.equal(r.mayWriteLedger,false);assert.equal(r.mayCallExchange,false);});
test('reporting cash, assigned margin and planned transfers without conflation',()=>{const r=run();assert.deepEqual(r.funds,{walletCashUSD:'2000',reportedIsolatedMarginUSD:'200',plannedMarginAddsUSD:'500',protectedCashUSD:'400'});assert.match(r.warnings[1],/excludes future planned transfers/);});
test('profile stress distances are labels and separately shown',()=>{assert.equal(run().profileReferenceFloorUSD,'60000');const x=run({riskFloorUSD:'65000',buyLadderLowerBoundUSD:'65000'});assert.equal(x.profileReferenceFloorUSD,'60000');assert.equal(x.riskFloorDiffersFromProfileReference,true);});
test('strong invalid input rejects unknown finance/authorization fields',()=>{fail({approved:true},'INVALID_INPUT_FIELDS');fail({walletCashUSD:2000},'INVALID_WALLETCASHUSD');fail({nominalCycleBudgetUSD:'1e4'},'INVALID_NOMINALCYCLEBUDGETUSD');});
test('reject negative and noncanonical numeric amounts',()=>{fail({walletCashUSD:'-1'},'INVALID_WALLETCASHUSD');fail({firstEntryPriceUSD:'080000'},'INVALID_FIRSTENTRYPRICEUSD');});
test('reject invalid profile/mode/versions and cycle limit',()=>{fail({profile:'unsafe'},'INVALID_PROFILE');fail({mode:'live'},'INVALID_MODE');fail({schemaVersion:2},'UNSUPPORTED_SCHEMA');fail({maxCycles:13},'INVALID_CYCLE_COUNT');});
test('reject lower bound below floor and incompatible references',()=>{fail({buyLadderLowerBoundUSD:'59000'},'INVALID_LADDER_LOWER_BOUND');fail({riskFloorUSD:'81000'},'INVALID_PRICE_REFERENCE_OR_FLOOR');});
test('reject impossible last price',()=>fail({mode:'adjustable-preview',withinCycleReinforcementGapUSD:'80000'},'NONPOSITIVE_ENTRY_PRICE'));
test('protected wallet reserve mismatch is an explicit blocker, not a transfer',()=>{const x=run({walletCashUSD:'100',protectedCashUSD:'500'});assert.ok(x.blockers.some(b=>b.code==='PROTECTED_RESERVE_EXCEEDS_REPORTED_WALLET'));});
test('decimal integer-safe exact nominal split',()=>{const x=run({nominalCycleBudgetUSD:'999.999999'});assert.deepEqual(x.levels.slice(0,3).map(r=>r.nominalAllocationUSD),['199.999999','299.999999','499.999999']);});
test('input not modified and output deep frozen',()=>{const input={...base};const r=contract.generate(input);assert.deepEqual(input,base);assert.ok(Object.isFrozen(r)&&Object.isFrozen(r.levels)&&Object.isFrozen(r.levels[0]));});
test('no apply or mutation function is exported',()=>assert.deepEqual(Object.keys(contract).sort(),['ContractError','MODES','PROFILE_DISTANCE','VERSION','generate'].sort()));
